// Agama x Arrow on Monad Testnet. Addresses come from the Foundry deployment
// (deployments/10143.json), regenerated by scripts/sync-monad.mjs.
import { defineChain, stringToHex } from 'viem';
import { monadTestnet as base } from 'viem/chains';

import { deployments } from './generated/deployments';
import type { Deployment } from './deployment-types';

// Monad Testnet by default. A local anvil (chain 31337) is how the browser
// flows get tested without spending testnet MON:
//   NEXT_PUBLIC_MONAD_CHAIN_ID=31337 NEXT_PUBLIC_MONAD_RPC=http://127.0.0.1:8545 pnpm dev
export const CHAIN_ID = Number(process.env.NEXT_PUBLIC_MONAD_CHAIN_ID ?? 10143);
export const CHAIN_ID_HEX = `0x${CHAIN_ID.toString(16)}`;
const IS_LOCAL = CHAIN_ID === 31337;

/// Every read endpoint we know for this chain. The client ranks them by
/// measured latency and moves off any that starts failing, so one public RPC
/// rate limiting is a slower page, not a dead one.
export const READ_RPCS = process.env.NEXT_PUBLIC_MONAD_RPC
  ? [process.env.NEXT_PUBLIC_MONAD_RPC]
  : IS_LOCAL
    ? ['http://127.0.0.1:8545']
    : ['https://testnet-rpc.monad.xyz', 'https://rpc.ankr.com/monad_testnet', 'https://monad-testnet.drpc.org'];

export const monadChain = defineChain({
  ...base,
  id: CHAIN_ID,
  name: IS_LOCAL ? 'Monad (local)' : 'Monad Testnet',
  rpcUrls: { default: { http: READ_RPCS } },
  blockExplorers: { default: { name: 'MonadVision', url: 'https://testnet.monadvision.com' } },
  contracts: { multicall3: { address: '0xcA11bde05977b3631167028862bE2a173976CA11' } },
});

/// Undefined until the contracts are deployed on this chain: every page shows
/// a notice instead of reading addresses that do not exist.
export const D: Deployment | undefined = deployments[CHAIN_ID];
export const DEPLOYED = !!D;
const ZERO = '0x0000000000000000000000000000000000000000' as const;
const zeroed = <T extends object>(o: T | undefined, keys: string[]): T =>
  (o ?? Object.fromEntries(keys.map((k) => [k, ZERO]))) as T;
export const ADDR = zeroed(D?.contracts, [
  'oracle', 'agUSD', 'sagUSD', 'queue', 'pool', 'stabilityPool', 'factory', 'earnRouter', 'amplifyRouter',
]) as Deployment['contracts'];
export const TOKENS = zeroed(D?.tokens, ['USDC', 'wTSLAx', 'wNVDAx', 'wSPYx', 'wAAPLx']) as Deployment['tokens'];
export const ADAPTERS = zeroed(D?.adapters, ['TSLA', 'NVDA', 'SPY', 'AAPL', 'VAULT']) as Deployment['adapters'];

export const EXPLORER = monadChain.blockExplorers.default.url;
export const txUrl = (hash: string) => `${EXPLORER}/tx/${hash}`;
export const addressUrl = (a: string) => `${EXPLORER}/address/${a}`;

/// A file from this app's own public/. app.agama.finance proxies this app and
/// serves its own public/ on that path, so anything only we have must be
/// fetched from where it actually exists.
export const asset = (path: string) => `${process.env.NEXT_PUBLIC_ASSET_PREFIX ?? ''}${path}`;
export const MON_FAUCET = 'https://faucet.monad.xyz';

export const USDC_DECIMALS = 6;
export const STOCK_DECIMALS = 18;
export const BPS = 10_000n;
export const RAY = 10n ** 27n;
/// The vault keeps 18 decimals over a 6-decimal USDC, so its assets are agUSD.
export const AG_PER_USDC = 10n ** 12n;

export type StockKey = 'TSLA' | 'NVDA' | 'SPY' | 'AAPL';

export interface Stock {
  key: StockKey;
  /// The ERC-4626 wrapper the lending markets take. An implementation detail:
  /// the app speaks the base token, the one people hold and trade.
  wrapper: 'wTSLAx' | 'wNVDAx' | 'wSPYx' | 'wAAPLx';
  /// The xStock itself, and the only name shown.
  base: 'TSLAx' | 'NVDAx' | 'SPYx' | 'AAPLx';
  name: string;
  ticker: `0x${string}`; // bytes32, right padded
}

export const STOCKS: Stock[] = [
  { key: 'TSLA', wrapper: 'wTSLAx', base: 'TSLAx', name: 'Tesla', ticker: stringToHex('TSLA', { size: 32 }) },
  { key: 'NVDA', wrapper: 'wNVDAx', base: 'NVDAx', name: 'NVIDIA', ticker: stringToHex('NVDA', { size: 32 }) },
  { key: 'SPY', wrapper: 'wSPYx', base: 'SPYx', name: 'S&P 500 ETF', ticker: stringToHex('SPY', { size: 32 }) },
  { key: 'AAPL', wrapper: 'wAAPLx', base: 'AAPLx', name: 'Apple', ticker: stringToHex('AAPL', { size: 32 }) },
];

/// Shown until the vault has two NAV snapshots to measure a realized APY from.
export const TARGET_VAULT_APY_RAY = 10n ** 26n; // 10%
